// Q-L1-14: port-name shims between sflc-generated instances and the replacement modules.
// sram_ctrl_sfl.ack is a level "idle" (core.sflp issues a command only while sram.ack
// is 1 and treats ack as completion); Pocket/rtl/sram_ctrl.sv exposes busy and a pulse.
module sram_ctrl_sfl (p_reset, m_clock, adrs, din, read, write, dout, ack,
                      OEn, WEn, UBn, LBn, DEn, ADDR, Din, Dout);
  input p_reset, m_clock;
  input [16:0] adrs; input [15:0] din; input read, write;
  output [15:0] dout; output ack;
  output OEn, WEn, UBn, LBn, DEn; output [16:0] ADDR; output [15:0] Din;
  input [15:0] Dout;
  wire busy;
  sram_ctrl u (.clk(m_clock), .rst(p_reset), .rd_req(read), .wr_req(write), .adrs(adrs),
               .wdata(din), .ack(), .dout(dout), .busy(busy), .OEn(OEn), .WEn(WEn),
               .UBn(UBn), .LBn(LBn), .DEn(DEn), .ADDR(ADDR), .Din(Din), .Dout(Dout));
  assign ack = ~busy;
endmodule

